// Defense in depth -- 01's tool schema already constrains reason/priority
// to an enum, but re-validate here rather than trust the caller blindly,
// same as every other sub-workflow in this codebase.
const input = $input.first().json;
const validReasons = ['low_confidence', 'customer_requested_human', 'angry_customer', 'legal_issue', 'refund_requested', 'sensitive_info', 'no_trusted_source', 'action_exceeds_permissions', 'hot_lead', 'other'];
const validPriorities = ['low', 'normal', 'high', 'urgent'];

const reason = validReasons.includes(input.reason) ? input.reason : 'other';
const priority = validPriorities.includes(input.priority) ? input.priority : 'normal';
const contextSummary = input.context_summary && String(input.context_summary).trim()
  ? String(input.context_summary).trim()
  : 'No summary provided by the agent.';

return [{ json: { tenant_id: input.tenant_id, conversation_id: input.conversation_id, reason, priority, context_summary: contextSummary } }];

// Same raw RFC 2822 base64url pattern as 15/18/20.
// notify_email may hold several comma-separated addresses (see escalation_recipients()).
// 0033: the email now carries everything the agent needs to act without
// opening anything: who the client is and how to reach them, Elliot's
// summary of what they need, and the conversation so far.
const DASHBOARD_URL = 'https://app.getelliot.eu'; // change if the dashboard moves to its own domain
const d = $json;
const input = $('Validate And Default').item.json;
const ctx = d.context || {};
const REASON = {
  hot_lead: 'Hot lead ready to talk',
  customer_requested_human: 'Visitor asked for a person',
  angry_customer: 'Upset visitor',
  legal_issue: 'Legal question',
  refund_requested: 'Refund request',
  sensitive_info: 'Sensitive information shared',
  low_confidence: 'Elliot was not sure of the answer',
  no_trusted_source: 'No answer in the knowledge base',
  action_exceeds_permissions: 'Request Elliot is not allowed to handle',
  other: 'Follow-up needed',
};
const CHANNEL = { whatsapp: 'WhatsApp', chat_widget: 'Website chat', email: 'Email', sms: 'SMS' };
const label = REASON[input.reason] || 'Needs a person';
const link = `${DASHBOARD_URL}/dashboard/conversations/${input.conversation_id}`;
const client = ctx.contact_name || ctx.contact_phone || ctx.contact_email || 'A client';
const urgent = input.priority === 'urgent' || input.priority === 'high';
const subject = `[Elliot] ${label}: ${client}${urgent ? ' (' + input.priority + ')' : ''}`;
const encodedSubject = `=?UTF-8?B?${Buffer.from(subject, 'utf8').toString('base64')}?=`;
const lines = [
  `${label} -- ${d.tenant_name}`,
  '',
  'WHAT THEY NEED',
  input.context_summary,
  '',
  'CLIENT',
  `Name:    ${ctx.contact_name || 'not given'}`,
  `Phone:   ${ctx.contact_phone || 'not given'}`,
  `Email:   ${ctx.contact_email || 'not given'}`,
  `Channel: ${CHANNEL[ctx.channel] || ctx.channel || 'unknown'}`,
  '',
  `Open the conversation (you can take over the chat from there):`,
  link,
];
if (ctx.transcript) {
  lines.push('', 'CONVERSATION SO FAR', ctx.transcript);
}
const body = lines.join('\n') + '\n';
const raw =
  `To: ${d.notify_email}\r\n` +
  `Subject: ${encodedSubject}\r\n` +
  `MIME-Version: 1.0\r\n` +
  `Content-Type: text/plain; charset=UTF-8\r\n` +
  `Content-Transfer-Encoding: base64\r\n\r\n` +
  Buffer.from(body, 'utf8').toString('base64');
const encoded = Buffer.from(raw).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
return [{ json: { ...d, subject, body, raw_message: encoded } }];

// Final return value for the Execute Workflow node in 01 -- always return
// the escalation_id regardless of which branch (notified or not) ran.
return [{ json: { escalation_id: $('Insert Escalation').item.json.escalation_id, reason: $('Validate And Default').item.json.reason, priority: $('Validate And Default').item.json.priority } }];
